import re

def parse_duration(s: str) -> int:
    pattern = r'(\d+)([hms])'
    matches = re.findall(pattern, s)
    total = 0
    for num, unit in matches:
        num = int(num)
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
    return total
